var o=[{title:`O seu stress total`,text:`O treino é apenas uma parte do stress que carrega. O sono fraco, as viagens, um trabalho exigente, a tensão emocional, o calor e uma doença recente podem afetar a concentração, a coordenação e a dificuldade que o trabalho parece ter. A prontidão não é um diagnóstico, e nenhuma pontuação a capta sozinha.`},{title:`Um balanço simples`,text:`Antes de um treino, repare no sono, na energia, na motivação, nas dores musculares e em quaisquer sintomas novos. Compare-os com o que é normal para si e não com os números de outra pessoa. O aquecimento dá-lhe uma segunda verificação: se os movimentos parecerem inesperadamente difíceis ou o seu controlo estiver alterado, uma sessão exigente pode precisar de ser ajustada.`},{title:`Ajustar num dia fraco`,text:`Num dia de pouca energia, reduza a carga, encurte a sessão, escolha exercícios mais simples ou faça antes uma caminhada fácil. Num dia normal, faça o plano como está escrito. Não transforme cada pequena quebra num dia de descanso. As tendências ao longo de várias sessões dizem-lhe mais do que uma única avaliação.`},{title:`Doença e segurança`,text:`Febre, doença que afeta o corpo todo, sintomas no peito ou falta de ar invulgar são razões para deixar o treino intenso e procurar aconselhamento médico. O popular “teste do pescoço” é apenas uma regra aproximada e não o autoriza a fazer exercício estando doente.`},{title:`Usar o TrainUp`,text:`O TrainUp não prescreve pesos, por isso escolhe a carga todos os dias. O seu plano só muda quando o gera de novo, com base no esforço (RPE) que avaliou depois de cada sessão, em qualquer dor que tenha indicado e na parte de cada treino que concluiu.`}];var s=[{label:`CDC: recomendações de sono`,url:`https://www.cdc.gov/sleep/about/`},{label:`Posicionamento do ACSM 2026`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`},{label:`NHS: dor no peito e sintomas de emergência`,url:`https://www.nhs.uk/symptoms/chest-pain/`}];var n={sections:o,sources:s};export{n as default,o as sections,s as sources};